export type CodecStatus = "ok" | "wrong_message_id" | "wrong_frame_format" | "unexpected_length" | "value_out_of_range" | "constant_mismatch" | "checksum_mismatch" | "unsupported_semantics";
export function lookup(bus: string, id: number) {
  return Object.entries(METADATA).flatMap(([key, message]) => message.instances.filter(instance => instance.bus === bus && instance.id === id).map(instance => ({ key, message, instance })))[0];
}
// Custom vendor payloads are intentionally raw compatibility artifacts until Stage 5.
export function decodeRaw(key: keyof typeof METADATA, payload: Uint8Array): [CodecStatus, Uint8Array?] {
  const message = METADATA[key];
  if (payload.length !== message.dlc) return ["unexpected_length"];
  if (message.layout.kind === "opaque" && "semantic_support" in message.layout) return ["unsupported_semantics", payload.slice()];
  return ["ok", payload.slice()];
}
